// Docs search: filters the topic index (title, label, summary, headings)
// generated by site/scripts/sync-docs.sh.
//
// Deliberately dependency-free. 113 topics is small enough that a linear
// scan per keystroke is imperceptible, so there is no index library to
// vendor and no external request to make.
(function () {
  var input = document.getElementById('docs-search-input');
  if (!input) return;

  var box = document.getElementById('docs-search-results');
  var empty = document.getElementById('docs-search-empty');
  // Zola's get_url(path='/') yields the base_url WITHOUT a trailing slash
  // ("https://host/lattice"), so normalise before concatenating paths.
  var base = document.querySelector('.docs-search').dataset.base || '/';
  if (base.charAt(base.length - 1) !== '/') base += '/';
  var entries = null;
  var loading = false;
  var active = -1;

  function load() {
    if (entries || loading) return;
    loading = true;
    fetch(base + 'docs-search.json')
      .then(function (r) { return r.json(); })
      .then(function (data) { entries = data; loading = false; run(); })
      .catch(function () { loading = false; });
  }

  // Score a topic against the query. Earlier, more prominent matches win:
  // the label a person actually browses beats a passing mention in a heading.
  function score(entry, q) {
    var label = entry.l.toLowerCase();
    var title = entry.t.toLowerCase();
    if (label === q || title === q) return 0;
    if (label.indexOf(q) === 0) return 1;
    if (title.indexOf(q) === 0) return 2;
    if (label.indexOf(q) !== -1 || title.indexOf(q) !== -1) return 3;
    if ((entry.g || '').toLowerCase().indexOf(q) !== -1) return 4;
    if ((entry.d || '').toLowerCase().indexOf(q) !== -1) return 5;
    if ((entry.h || '').toLowerCase().indexOf(q) !== -1) return 6;
    return -1;
  }

  function render(hits, q) {
    box.replaceChildren();
    active = -1;
    hits.forEach(function (hit, i) {
      var a = document.createElement('a');
      a.href = base + hit.u;
      a.className = 'docs-search-hit';
      a.setAttribute('role', 'option');

      var name = document.createElement('span');
      name.className = 'hit-name';
      name.textContent = hit.l;

      var where = document.createElement('span');
      where.className = 'hit-where';
      where.textContent = hit.g ? hit.s + ' · ' + hit.g : hit.s;

      a.appendChild(name);
      a.appendChild(where);

      if (hit.d) {
        var desc = document.createElement('span');
        desc.className = 'hit-desc';
        desc.textContent = hit.d;
        a.appendChild(desc);
      }
      box.appendChild(a);
    });
    box.hidden = hits.length === 0;
    empty.hidden = !(q && hits.length === 0);
  }

  function run() {
    var q = input.value.trim().toLowerCase();
    if (!q) {
      box.hidden = true;
      empty.hidden = true;
      return;
    }
    if (!entries) { load(); return; }

    var hits = [];
    for (var i = 0; i < entries.length; i++) {
      var s = score(entries[i], q);
      if (s !== -1) hits.push({ s: s, i: i, e: entries[i] });
    }
    hits.sort(function (a, b) { return a.s - b.s || a.i - b.i; });
    render(hits.slice(0, 12).map(function (h) { return h.e; }), q);
  }

  function move(delta) {
    var items = box.querySelectorAll('.docs-search-hit');
    if (!items.length) return;
    if (active >= 0) items[active].classList.remove('active');
    active = (active + delta + items.length) % items.length;
    items[active].classList.add('active');
    items[active].scrollIntoView({ block: 'nearest' });
  }

  input.addEventListener('focus', load);
  input.addEventListener('input', run);

  input.addEventListener('keydown', function (e) {
    var items = box.querySelectorAll('.docs-search-hit');
    // C-n / C-p alongside the arrows — this is a vim editor's manual.
    if (e.key === 'ArrowDown' || (e.ctrlKey && e.key === 'n')) {
      e.preventDefault(); move(1);
    } else if (e.key === 'ArrowUp' || (e.ctrlKey && e.key === 'p')) {
      e.preventDefault(); move(-1);
    } else if (e.key === 'Enter') {
      if (active >= 0 && items[active]) { e.preventDefault(); items[active].click(); }
      else if (items.length) { e.preventDefault(); items[0].click(); }
    } else if (e.key === 'Escape') {
      input.value = ''; run(); input.blur();
    }
  });

  document.addEventListener('click', function (e) {
    if (!e.target.closest('.docs-search')) { box.hidden = true; empty.hidden = true; }
  });

  // `/` focuses search, the way it would inside the editor.
  document.addEventListener('keydown', function (e) {
    if (e.key !== '/' || e.metaKey || e.ctrlKey || e.altKey) return;
    var t = e.target.tagName;
    if (t === 'INPUT' || t === 'TEXTAREA' || e.target.isContentEditable) return;
    e.preventDefault();
    input.focus();
    input.select();
  });
})();
